import { expect, expectStatus, test } from "../../fixtures";

test("a page past the last vendor is empty but still reports the total", { tag: "@LIF-15" }, async ({ apiAs }) => {
  // Arrange: the total as seen from the first page. Tests share one database, so the offset
  // sits well past the total to stay beyond it even if other tests add vendors meanwhile.
  const member = await apiAs("member");
  const first = await expectStatus<{ items: unknown[]; total: number }>(
    await member.get("/api/vendors", { params: { limit: 20, offset: 0 } }),
    200,
  );
  const offset = first.total + 1000;

  // Act
  const response = await member.get("/api/vendors", { params: { limit: 20, offset } });

  // Assert
  const page = await expectStatus<{ items: unknown[]; total: number; offset: number }>(response, 200);
  expect(page.items, await response.text()).toEqual([]);
  expect(page.total).toBe(first.total);
  expect(page.offset).toBe(offset);
});
